import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const EmployeeManagementPage = () => {
  const navigate = useNavigate();
  const [employees, setEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedEmployees, setSelectedEmployees] = useState([]); // State to track selected employee IDs
  const [currentPage, setCurrentPage] = useState(1);
  const [totalEmployees, setTotalEmployees] = useState(0);
  const [pageSize, setPageSize] = useState(10); // Should match backend default

  // Fetch employees from the backend with pagination
  const fetchEmployees = async (page) => {
    setIsLoading(true);
    try {
      const response = await axios.get(`http://127.0.0.1:8000/api/employees/?page=${page}`);
      setEmployees(response.data.results);
      setTotalEmployees(response.data.count);
      setCurrentPage(page);
    } catch (error) {
      console.error("Error fetching employees:", error);
      // alert('Failed to fetch employee data. Please ensure backend is running.');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchEmployees(1); // Fetch the first page on initial load
  }, []);

  const handlePageChange = (newPage) => {
    fetchEmployees(newPage);
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedEmployees(employees.map(emp => emp.id));
    } else {
      setSelectedEmployees([]);
    }
  };

  const handleSelectOne = (e, id) => {
    if (e.target.checked) {
      setSelectedEmployees([...selectedEmployees, id]);
    } else {
      setSelectedEmployees(selectedEmployees.filter(empId => empId !== id));
    }
  };

  const handleRunPayroll = () => {
    if (selectedEmployees.length === 0) {
      alert("Please select at least one employee to run payroll.");
      return;
    }
    console.log("Running payroll for employee IDs:", selectedEmployees);
    navigate('/run-payroll'); // In a real app, pass selected IDs
  };

  const handleDelete = async (employeeId) => {
    const isConfirmed = window.confirm('Are you sure you want to delete this employee? This action cannot be undone.');
    if (isConfirmed) {
      try {
        await axios.delete(`http://127.0.0.1:8000/api/employees/${employeeId}/`);
        alert('Employee deleted successfully.');
        fetchEmployees(currentPage); // Re-fetch current page to update list
      } catch (error) {
        console.error('Error deleting employee:', error);
        alert('Failed to delete employee.');
      }
    }
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Staff & Faculty Directory</h1>
          <p className="text-sm text-subtext-light">{selectedEmployees.length} employee(s) selected</p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={handleRunPayroll}
            disabled={selectedEmployees.length === 0}
            className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600 disabled:bg-gray-400"
          >
            <span className="material-icons mr-2 text-base">play_arrow</span> Run Payroll for Selected
          </button>
          <Link to="/add-employee" className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium">Add New Staff</Link>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-md">
        {isLoading ? (
          <div className="text-center py-8">Loading staff data from the server...</div>
        ) : employees.length === 0 ? (
          <div className="text-center py-8 text-subtext-light">No employees found.</div>
        ) : (
          <>
            <table className="w-full text-sm text-left">
              <thead className="text-xs uppercase bg-background-light">
                <tr>
                  <th className="p-4">
                    <input
                      type="checkbox"
                      className="form-checkbox"
                      onChange={handleSelectAll}
                      checked={selectedEmployees.length === employees.length && employees.length > 0}
                    />
                  </th>
                  <th className="px-6 py-3">Staff ID</th> {/* Re-added Staff ID header */}
                  <th className="px-6 py-3">Name</th>
                  <th className="px-6 py-3">Designation</th>
                  <th className="px-6 py-3">Department</th>
                  <th className="px-6 py-3">Email</th>
                  <th className="px-6 py-3 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {employees.map((employee) => (
                  <tr key={employee.id} className="border-b hover:bg-gray-50">
                    <td className="w-4 p-4">
                      <input
                        type="checkbox"
                        className="form-checkbox"
                        onChange={(e) => handleSelectOne(e, employee.id)}
                        checked={selectedEmployees.includes(employee.id)}
                      />
                    </td>
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">{employee.employeeId}</td> {/* Displays Staff ID */}
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">
                      <Link to={`/employees/${employee.id}`} className="hover:text-primary">
                        {employee.firstName} {employee.lastName}
                      </Link>
                    </td>
                    <td className="px-6 py-4">{employee.designation}</td>
                    <td className="px-6 py-4">{employee.department}</td>
                    <td className="px-6 py-4">{employee.personalEmail}</td>
                    <td className="px-6 py-4 text-center space-x-4">
                      <Link to={`/employees/edit/${employee.id}`} className="text-primary hover:underline text-xs font-medium">
                        Edit
                      </Link>
                      <button onClick={() => handleDelete(employee.id)} className="text-red-500 hover:underline text-xs font-medium">
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            <PaginationControls
              currentPage={currentPage}
              totalItems={totalEmployees}
              pageSize={pageSize}
              onPageChange={handlePageChange}
            />
          </>
        )}
      </div>
    </div>
  );
};

// Reusable Pagination Component (remains the same)
const PaginationControls = ({ currentPage, totalItems, pageSize, onPageChange }) => {
  const totalPages = Math.ceil(totalItems / pageSize);
  const showingFrom = (currentPage - 1) * pageSize + 1;
  const showingTo = Math.min(currentPage * pageSize, totalItems);

  if (totalPages <= 1) return null;

  return (
    <nav aria-label="Table navigation" className="flex items-center justify-between pt-4">
      <span className="text-sm font-normal text-subtext-light">
        Showing <span className="font-semibold text-text-light">{showingFrom}-{showingTo}</span> of <span className="font-semibold text-text-light">{totalItems}</span>
      </span>
      <ul className="inline-flex h-8 -space-x-px text-sm">
        <li>
          <button
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage === 1}
            className="ml-0 flex h-8 items-center justify-center rounded-l-lg border border-border-light bg-card-light px-3 text-subtext-light hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Previous
          </button>
        </li>
        <li>
          <button
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage === totalPages}
            className="flex h-8 items-center justify-center rounded-r-lg border border-border-light bg-card-light px-3 text-subtext-light hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Next
          </button>
        </li>
      </ul>
    </nav>
  );
};

export default EmployeeManagementPage;
